#!/usr/bin/env bash
# PARCOURS sur la carte des entités : analyse du backend (ce que chaque procédure lit / écrit / envoie),
# sélecteur « Parcours » avec pas-à-pas sur la molécule, 4 parcours dans « Les demandes », vérifications dans pnpm check.
# Prérequis : apply-carte-entites.sh.
# Usage (racine du repo) : bash apply-parcours.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/src/features/docs/entities/stories.ts" 2>/dev/null | grep -qF "export function readChapterStories"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "export function parsePrismaSchema" "apps/web/src/features/docs/entities/prismaSchema.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-carte-entites.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx" "apps/web/content/docs/dev/membres/demandes.mdx" "apps/web/src/app/docs/[...slug]/page.tsx" "apps/web/src/features/docs/entities/EntityExplorer.tsx" "apps/web/src/features/docs/entities/chapterGraph.ts" "apps/web/src/features/docs/lib/docs.source.ts" "apps/web/src/features/docs/lib/docs.types.ts" "package.json" "scripts/check-doc-entities.mjs")
CREATED=("apps/web/src/features/docs/entities/procedureMap.generated.json" "apps/web/src/features/docs/entities/stories.ts" "scripts/build-procedure-map.mjs")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "export function readChapterStories" "apps/web/src/features/docs/entities/stories.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/src/features/docs/entities"
base64 -d > "apps/web/src/features/docs/entities/procedureMap.generated.json" <<'B64'
